#include <algorithm>
#include <cstdint>
#include <functional>
#include <iostream>
#include <limits>
#include <numeric>
#include <optional>
#include <random>
#include <set>
#include <stdexcept>
#include <utility>
#include <vector>
#include "combinatorial_optimization/all.hpp"
namespace {
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
template<class E,class F>void rejects(F fn){bool caught=false;try{fn();}catch(const E&){caught=true;}require(caught,"expected exception");}
using Matrix=std::vector<std::vector<std::optional<long long>>>;
using W=cp::OptimizationWide;
std::optional<long long> assignment(const Matrix&a,int m,bool maximize){std::optional<long long> best;std::function<void(int,unsigned,long long)>dfs=[&](int row,unsigned used,long long sum){if(row==int(a.size())){if(!best||(maximize?sum>*best:sum<*best))best=sum;return;}for(int col=0;col<m;++col)if(!(used>>col&1)&&a[row][col])dfs(row+1,used|(1U<<col),sum+*a[row][col]);};dfs(0,0,0);return best;}
void certificate(const Matrix&a,int m,const std::optional<cp::AssignmentResult>&r,bool maximize){auto best=assignment(a,m,maximize);require(bool(r)==bool(best),"assignment feasibility");if(!r)return;require(r->cost==*best,"assignment cost vs injective maps");require(r->row_to_column.size()==a.size()&&int(r->column_to_row.size())==m,"assignment dimensions");std::set<int>used;W primal=0,dual=0;for(int i=0;i<int(a.size());++i){const int j=r->row_to_column[i];require(j>=0&&j<m&&a[i][j]&&used.insert(j).second&&r->column_to_row[j]==i,"matching is an injection of allowed cells");primal+=*a[i][j];dual+=r->row_potential[i];require(r->row_potential[i]+r->column_potential[j]==*a[i][j],"matched edge is tight");for(int k=0;k<m;++k)if(a[i][k])require(maximize?r->row_potential[i]+r->column_potential[k]>=*a[i][k]:r->row_potential[i]+r->column_potential[k]<=*a[i][k],"dual feasibility");}for(int j=0;j<m;++j){const auto v=r->column_potential[j];dual+=v;require(maximize?v>=0:v<=0,"rectangular column dual sign");if(!used.count(j))require(r->column_to_row[j]==-1&&v==0,"unused column potential is zero");}require(primal==dual&&primal==r->cost,"primal-dual optimality certificate");}
void assignments(std::mt19937_64&rng){std::size_t count=0;for(int n=0;n<=2;++n)for(int m=0;m<=3;++m){int states=1;for(int i=0;i<n*m;++i)states*=4;for(int code=0;code<states;++code){Matrix a(n,std::vector<std::optional<long long>>(m));int value=code;for(auto&row:a)for(auto&x:row){int z=value%4;value/=4;if(z)x=z-2;}cp::AssignmentProblem p(n,m);for(int i=0;i<n;++i)for(int j=0;j<m;++j)if(a[i][j])p.set_cost(i,j,*a[i][j]);certificate(a,m,p.solve(),false);certificate(a,m,p.solve(cp::AssignmentObjective::maximize),true);if(n)certificate(a,m,cp::hungarian(a),false);++count;}}
 for(int trial=0;trial<800;++trial){int n=rng()%6,m=rng()%7;Matrix a(n,std::vector<std::optional<long long>>(m));cp::AssignmentProblem p(n,m);for(int i=0;i<n;++i)for(int j=0;j<m;++j)if(rng()%4){a[i][j]=static_cast<long long>(rng()%41)-20;p.set_cost(i,j,*a[i][j]);}certificate(a,m,p.solve(),false);certificate(a,m,p.solve(cp::AssignmentObjective::maximize),true);auto first=p.solve();if(n&&m){p.forbid(0,0);a[0][0]=std::nullopt;certificate(a,m,p.solve(),false);if(first)require(first->row_to_column.size()==std::size_t(n),"old assignment result owns its arrays");}}
 std::cout<<count<<" optional cost matrices + 800 random assignments: exhaustive injections and all primal-dual certificates passed\n";}
int matching_size(const std::vector<unsigned>&adj,unsigned available,std::vector<int>&memo){if(!available)return 0;int&answer=memo[available];if(answer!=-1)return answer;int u=0;while(!(available>>u&1))++u;const unsigned rest=available&~(1U<<u);answer=matching_size(adj,rest,memo);for(int v=u+1;v<int(adj.size());++v)if((rest>>v&1)&&(adj[u]>>v&1))answer=std::max(answer,1+matching_size(adj,rest&~(1U<<v),memo));return answer;}
void matching_check(int n,const std::vector<std::pair<int,int>>&edges){cp::GeneralMatching graph(n);std::vector<unsigned>adj(n);for(auto[u,v]:edges){graph.add_edge(u,v);if(u!=v){adj[u]|=1U<<v;adj[v]|=1U<<u;}}auto r=graph.maximum_matching();std::vector<int>memo(1U<<n,-1);require(r.cardinality==matching_size(adj,(1U<<n)-1,memo),"blossom vs vertex-subset matching");require(r.pairs.size()==std::size_t(r.cardinality)&&r.mate.size()==std::size_t(n),"matching result dimensions");for(int v=0;v<n;++v)if(r.mate[v]!=-1)require(r.mate[v]!=v&&(adj[v]>>r.mate[v]&1)&&r.mate[r.mate[v]]==v,"general matching valid mates");for(auto[u,v]:r.pairs)require(u<v&&r.mate[u]==v,"sorted matched endpoints");require(graph.maximum_matching().mate==r.mate,"recompute from empty matching");}
void matchings(std::mt19937_64&rng){std::size_t count=0;for(int n=0;n<=6;++n){std::vector<std::pair<int,int>>edges;for(int u=0;u<n;++u)for(int v=u+1;v<n;++v)edges.emplace_back(u,v);for(unsigned mask=0;mask<(1U<<edges.size());++mask){std::vector<std::pair<int,int>>selected;for(std::size_t i=0;i<edges.size();++i)if(mask>>i&1)selected.push_back(edges[i]);matching_check(n,selected);++count;}}
 for(int trial=0;trial<700;++trial){int n=rng()%13;std::vector<std::pair<int,int>>edges;if(n)for(int i=0;i<60;++i)edges.emplace_back(rng()%n,rng()%n);matching_check(n,edges);std::shuffle(edges.begin(),edges.end(),rng);matching_check(n,edges);}for(int trial=0;trial<100;++trial){int l=rng()%8,r=rng()%8;cp::BipartiteMatching hk(l,r);cp::GeneralMatching blossom(l+r);for(int i=0;i<l;++i)for(int j=0;j<r;++j)if(rng()%2){hk.add_edge(i,j);blossom.add_edge(i,l+j);}require(hk.maximum_matching().cardinality==blossom.maximum_matching().cardinality,"general vs shared bipartite matching");}
 std::cout<<count<<" simple graphs through 6 vertices + 1400 shuffled multigraphs / 100 bipartite cross-checks passed\n";}
struct Edge{int a,b,cap,cost;};
std::vector<std::optional<long long>> flow_oracle(int n,const std::vector<Edge>&edges){int maxflow=0;for(auto e:edges)if(e.a==0)maxflow+=e.cap;std::vector<std::optional<long long>>best(maxflow+1);std::vector<int>balance(n);std::function<void(std::size_t,long long)>dfs=[&](std::size_t i,long long cost){if(i==edges.size()){for(int v=1;v+1<n;++v)if(balance[v])return;int f=balance[0];if(f<0||f>maxflow||balance[n-1]!=-f)return;if(!best[f]||cost<*best[f])best[f]=cost;return;}auto e=edges[i];for(int x=0;x<=e.cap;++x){balance[e.a]+=x;balance[e.b]-=x;dfs(i+1,cost+x*e.cost);balance[e.a]-=x;balance[e.b]+=x;}};dfs(0,0);return best;}
void flow_state(const cp::MinCostFlow<int,long long>&g,int n,int sent,long long cost){std::vector<int>balance(n);long long sum=0;for(const auto&e:g.edges()){require(e.flow>=0&&e.flow<=e.capacity,"flow capacity");balance[e.from]+=e.flow;balance[e.to]-=e.flow;sum+=e.flow*e.cost;}require(sum==cost&&balance[0]==sent&&balance[n-1]==-sent,"flow cost and terminals");for(int v=1;v+1<n;++v)require(!balance[v],"flow conservation");}
void flow_case(int n,const std::vector<Edge>&edges){auto truth=flow_oracle(n,edges);int maximum=int(truth.size())-1;while(!truth[maximum])--maximum;cp::MinCostFlow<int,long long>graph(n);for(auto e:edges)graph.add_edge(e.a,e.b,e.cap,e.cost);for(int limit=0;limit<=maximum+1;++limit){graph.reset_flow();auto r=graph.flow(0,n-1,limit);int want=std::min(limit,maximum);require(r.flow==want&&r.cost==*truth[want],"flow vs every integral edge assignment");flow_state(graph,n,want,*truth[want]);}
 graph.reset_flow();auto slope=graph.slope(0,n-1);require(slope.front().flow==0&&slope.front().cost==0&&slope.back().flow==maximum,"slope endpoints");for(std::size_t i=1;i<slope.size();++i){auto a=slope[i-1],b=slope[i];require(b.flow>a.flow,"slope flow increases");for(int f=a.flow;f<=b.flow;++f)require((b.cost-a.cost)*(f-a.flow)==(*truth[f]-a.cost)*(b.flow-a.flow),"slope interpolation equals optimal costs");if(i>1){auto p=slope[i-2];require((a.cost-p.cost)*(b.flow-a.flow)<(b.cost-a.cost)*(a.flow-p.flow),"strictly increasing marginal costs after coalescing");}}
 graph.reset_flow();long long cost=0;for(int i=1;i<=maximum+1;++i){auto r=graph.flow(0,n-1,1);int f=std::min(i,maximum);cost+=r.cost;require(r.flow==(i<=maximum?1:0)&&cost==*truth[f],"repeated calls add optimal flow and cost");flow_state(graph,n,f,cost);}}
void flows(std::mt19937_64&rng){int count=0;for(int mask=0;mask<729;++mask){int code=mask;std::vector<Edge>edges;for(auto[a,b]:std::vector<std::pair<int,int>>{{0,1},{0,2},{1,2}}){int cap=code%3;code/=3;int cost=code%3-1;code/=3;edges.push_back({a,b,cap,cost});}flow_case(3,edges);++count;}
 for(int trial=0;trial<400;++trial){int n=2+rng()%4;std::vector<Edge>edges;std::vector<int>p(n);for(auto&x:p)x=int(rng()%11)-5;for(int i=0;i<7;++i){int a=rng()%n,b=rng()%n;int cap=rng()%3;int cost=int(rng()%6)+p[b]-p[a];edges.push_back({a,b,cap,cost});}flow_case(n,edges);++count;}
 // The second augmenting path must cancel a previously selected assignment edge.
 flow_case(6,{{0,1,1,0},{0,2,1,0},{1,3,1,0},{1,4,1,1},{2,3,1,1},{2,4,1,100},{3,5,1,0},{4,5,1,0}});
 std::cout<<count+1<<" flow networks: all integral flows, slopes, additional calls, conservation and reverse rerouting passed\n";}
void extremes(){const auto hi=std::numeric_limits<long long>::max(),lo=std::numeric_limits<long long>::min();auto a=cp::hungarian(std::vector<std::vector<long long>>{{lo}});require(a->cost==lo&&a->row_potential[0]==W(lo),"minimum signed assignment weight");cp::AssignmentProblem p(1,1);p.set_cost(0,0,lo);require(p.solve(cp::AssignmentObjective::maximize)->cost==lo,"maximize LLONG_MIN without negating in narrow type");auto cancellation=cp::hungarian(std::vector<std::vector<long long>>{{hi,hi},{lo,lo}});require(cancellation->cost==-1,"assignment wide intermediate and cancellation");rejects<std::overflow_error>([&]{cp::hungarian(std::vector<std::vector<long long>>{{hi,hi},{hi,hi}});});rejects<std::invalid_argument>([]{cp::hungarian(std::vector<std::vector<long long>>{{1},{1,2}});});rejects<std::invalid_argument>([]{cp::AssignmentProblem(-1,0);});rejects<std::out_of_range>([]{cp::AssignmentProblem(1,1).set_cost(1,0,1);});rejects<std::invalid_argument>([]{cp::GeneralMatching(-1);});rejects<std::out_of_range>([]{cp::GeneralMatching(1).add_edge(0,1);});
 cp::MinCostFlow<> g(2);g.add_edge(0,1,1,lo);require(g.flow(0,1).cost==lo,"reverse cost wider than Cost");g.reset_flow();require(g.flow(0,1).cost==lo,"flow reset retains minimum cost");g.reset_flow();g.add_edge(0,0,2,0);require(g.flow(0,1,0).flow==0,"zero limit");rejects<std::logic_error>([&]{g.add_edge(0,1,1,0);});rejects<std::logic_error>([&]{g.flow(1,0);});g.reset_flow();g.add_edge(0,1,0,hi);
 cp::MinCostFlow<> overflow(2);overflow.add_edge(0,1,2,hi);rejects<std::overflow_error>([&]{overflow.flow(0,1,2);});require(overflow.get_edge(0).flow==0,"overflow rejects current augmentation before residual update");require(overflow.flow(0,1,1).cost==hi,"overflow leaves a consistent network");
 for(bool reachable:{false,true}){cp::MinCostFlow<> bad(4);bad.add_edge(0,3,1,0);bad.add_edge(1,2,1,-2);bad.add_edge(2,1,1,1);if(reachable)bad.add_edge(0,1,1,0);rejects<std::domain_error>([&]{bad.flow(0,3,1);});for(const auto&e:bad.edges())require(!e.flow,"negative cycle rejection before flow mutation");}
 cp::MinCostFlow<> self(2);self.add_edge(0,0,1,-1);rejects<std::domain_error>([&]{self.flow(0,1);});rejects<std::invalid_argument>([]{cp::MinCostFlow<>(-1);});rejects<std::out_of_range>([]{cp::MinCostFlow<>(2).flow(-1,1);});rejects<std::invalid_argument>([]{cp::MinCostFlow<>(2).flow(0,0);});rejects<std::invalid_argument>([]{cp::MinCostFlow<>(2).flow(0,1,-1);});rejects<std::invalid_argument>([]{cp::MinCostFlow<>(2).add_edge(0,1,-1,0);});rejects<std::out_of_range>([]{cp::MinCostFlow<>(2).get_edge(0);});cp::MinCostFlow<unsigned long long,int> wide(2);wide.add_edge(0,1,std::numeric_limits<unsigned long long>::max(),0);require(wide.flow(0,1).flow==std::numeric_limits<unsigned long long>::max(),"unsigned capacity maximum");std::cout<<"signed costs / unsigned capacities / wide intermediates, duals, overflow and invalid inputs passed\n";}
void large(){const int n=350,m=500;std::vector<std::vector<long long>>cost(n,std::vector<long long>(m));for(int i=0;i<n;++i)for(int j=0;j<m;++j)cost[i][j]=i==j?-1000:std::abs(i-j);auto r=cp::hungarian(cost);require(r->cost==-1000LL*n,"350x500 assignment");cp::GeneralMatching complete(500);for(int i=0;i<500;++i)for(int j=i+1;j<500;++j)complete.add_edge(i,j);require(complete.maximum_matching().cardinality==250,"500 vertex dense odd cycles");cp::MinCostFlow<> path(200000);for(int i=1;i<path.size();++i)path.add_edge(i-1,i,1000000000LL,1);auto f=path.flow(0,path.size()-1);require(f.flow==1000000000LL&&f.cost==199999000000000LL,"200000 vertex nonrecursive flow");std::cout<<"350x500 Hungarian / 500-vertex blossom / 200000-vertex flow passed\n";}
}
int main(){std::mt19937_64 rng(323023);assignments(rng);matchings(rng);flows(rng);extremes();large();}
